from pathlib import Path
import shutil
from html import escape

root = Path.cwd()
out = root / 'artifacts/caja-vista-previa'
out.mkdir(parents=True, exist_ok=True)
shutil.copyfile(root / 'src/SistemiPos.Web/wwwroot/css/site.css', out / 'site.css')
products = [('Coca-Cola 355 ml', 8, 48), ('Agua pura 600 ml', 5, 36),
            ('Té frío de limón', 7, 24), ('Jugo de naranja', 6, 18), ('Gaseosa de naranja', 8, 0)]
catalog = ''.join(f'''<div class="product-row {'is-unavailable' if stock == 0 else ''}" role="button"><strong class="product-list-name">{escape(name)}</strong><strong class="product-list-price">Q {price:.2f}</strong><span class="product-stock {'is-out' if stock == 0 else 'is-normal'}">{'Agotado' if stock == 0 else f'Existencia: {stock}'}</span><button type="button" class="button-secondary product-detail-button">Detalle</button></div>''' for name,price,stock in products)
cart = ''
for name, price, qty in [('Coca-Cola 355 ml',8,2),('Agua pura 600 ml',5,1)]:
    cart += f'''<div class="sale-line"><div class="sale-line-copy"><strong>{escape(name)}</strong><span>Q {price:.2f} c/u</span><button type="button" class="line-discount-link">Aplicar descuento</button></div><div class="line-quantity-controls"><button type="button">−</button><input value="{qty}" readonly><button type="button">+</button></div><strong class="sale-line-total">Q {price*qty:.2f}</strong><button type="button" class="icon-button remove-line">×</button></div>'''
html = '''<!doctype html><html lang="es-GT"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pantalla de ventas para caja - Vista previa ilustrativa</title><link rel="stylesheet" href="site.css"><style>
.preview-label{background:#fff7df;border-bottom:1px solid #e8d49c;color:#6c561a;padding:9px 16px;font-size:12px;text-align:center}.preview-label strong{letter-spacing:.04em}body.app-body,.app-shell,.workspace{height:auto;min-height:100vh;overflow:visible}.topbar{position:static}.preview-branch{font-size:12px;font-weight:650;white-space:nowrap}.preview-note{font-size:11px;color:#687d8e;margin:0;padding:0 20px 12px}.product-stock.is-normal{font-size:.72rem}.pos-top-nav-link{pointer-events:none}.pos-page{display:block!important}.checkout-total .total-row.total{font-size:1.2rem}button{cursor:default}.content{padding-bottom:14px}.catalog-toolbar>.field{min-width:170px}.pos-checkout{position:static}
</style></head><body class="app-body pos-terminal"><div class="preview-label"><strong>VISTA PREVIA ILUSTRATIVA</strong> · Pantalla de ventas basada en las vistas y estilos actuales · Datos de ejemplo</div><div class="app-shell"><div class="workspace"><header class="topbar"><div class="topbar-leading"><div class="breadcrumbs"><span>Ventas</span><span>›</span><span>Nueva venta</span></div></div><div class="topbar-actions"><nav class="pos-top-navigation"><a class="pos-top-nav-link is-active">Panel de venta</a><a class="pos-top-nav-link">Pedidos</a><a class="pos-top-nav-link">Entrada o salida</a><a class="pos-top-nav-link">Cerrar caja</a></nav><span class="preview-branch">Sucursal de ejemplo</span><div class="topbar-user"><span class="user-avatar">CE</span><span class="topbar-user-copy"><strong>Usuario: cajero.ejemplo</strong><small>Rol: Punto de Venta</small></span></div><button class="icon-button logout-button">Salir</button></div></header><main class="content"><div class="pos-page"><div class="pos-layout"><section class="product-browser form-card"><div class="catalog-toolbar"><div class="field"><label>Terminal</label><select class="input"><option>CAJA-01</option></select></div><div><p class="eyebrow">Catálogo</p><h2>Productos</h2></div><span class="catalog-result-count">5 productos</span></div><label class="interactive-product-search"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg><input class="input" placeholder="Buscar por nombre, código o código de barras" readonly></label><p class="pos-interaction-hint">Haz doble clic sobre un producto para agregarlo a la venta.</p><div class="product-list"><div class="product-list-header"><span>Nombre</span><span>Precio</span><span>Existencia</span><span>Acción</span></div>'''
html += catalog
html += '''</div></section><aside class="pos-checkout"><section class="form-card checkout-card"><div class="checkout-header"><div><p class="eyebrow">Venta actual</p><h2>Productos agregados</h2></div><span class="line-count">2</span></div><div class="checkout-lines">'''
html += cart
html += '''</div><div class="checkout-total"><div class="total-row"><span>Subtotal</span><strong>Q 21.00</strong></div><div class="total-row"><span>Descuento</span><strong>Q 0.00</strong></div><div class="total-row total"><span>Total</span><strong>Q 21.00</strong></div></div><div class="checkout-actions checkout-primary-action"><button type="button" class="button-primary">COBRAR Q 21.00</button><button type="button" class="button-secondary">Generar proforma</button></div></section></aside></div></div></main><p class="preview-note">Ejemplo visual del panel de ventas para caja. Los productos e importes son ficticios; esta imagen no confirma una venta ni una sesión operativa.</p></div></div></body></html>'''
(out / 'ventas.html').write_text(html,encoding='utf-8')
print(out / 'ventas.html')
